// Copy the app's own screenshots and logo into public/ at build time.
//
// Copied, not committed twice: store/screenshots/ is regenerated by
// `npm run screenshots:store` from the real app against the demo Xtream
// server, and a second copy here would be the one that quietly goes stale.
import { cpSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const site = join(dirname(fileURLToPath(import.meta.url)), '..');
const repo = join(site, '..');

mkdirSync(join(site, 'public'), { recursive: true });
cpSync(join(repo, 'store/screenshots'), join(site, 'public/screenshots'), { recursive: true });
cpSync(join(repo, 'assets/icon.svg'), join(site, 'public/logo.svg'));
cpSync(join(repo, 'assets/icon130.png'), join(site, 'public/icon.png'));

// TMDB's approved logo, from the app's own attribution, so the credits page
// shows exactly what the app does.
const attribution = readFileSync(join(repo, 'src/components/tmdb-attribution.ts'), 'utf8');
const logo = attribution.match(/TMDB_LOGO = '(<svg[^']+<\/svg>)'/)?.[1];
if (!logo) throw new Error('TMDB_LOGO not found in src/components/tmdb-attribution.ts');
writeFileSync(join(site, 'public/tmdb-logo.svg'), logo.replace('<svg ', '<svg xmlns="http://www.w3.org/2000/svg" '));

console.log('copied screenshots and logo into the site');
